files = {}
for p in problems:
    path = p['path']
    if path not in files:
        with open(path, 'r', encoding='utf-8') as f:
            files[path] = f.readlines()
    
    line_idx = p['startLine'] - 1
    line = files[path][line_idx]
    
    msg = p['message']
    
    # The class `...` can be written as `...`
    if "The class `" in msg:
        m = re.search(r"The class `(.*?)` can be written as `(.*?)`", msg)
        if m:
            old_c = m.group(1)
            new_c = m.group(2)
            line = line.replace(old_c, new_c)
            files[path][line_idx] = line
            
    # Props must be serializable
    elif "Props must be serializable" in msg:
        line = line.replace("onClose", "onCloseAction")
        files[path][line_idx] = line

for path, lines in files.items():
    with open(path, 'w', encoding='utf-8') as f:
        f.writelines(lines)
